namespace sv_0901af41001b4e19b3e7491ebe4ec7dc.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service — one instance per circuit, so each user gets independent state.
/// Static SSR components don't participate in a circuit, which is why we pair this
/// with interactive islands that read/write browser localStorage via JS interop.
/// </summary>
public sealed class ThemeService
{
    public ThemeMode Theme { get; private set; } = ThemeMode.System;
    public string AccentColor { get; private set; } = "#0d6efd";

    public event Action? OnChanged;

    public void SetTheme(ThemeMode theme)
    {
        if (Theme == theme) return;
        Theme = theme;
        OnChanged?.Invoke();
    }

    public void SetAccentColor(string color)
    {
        if (AccentColor == color) return;
        AccentColor = color;
        OnChanged?.Invoke();
    }

    public void Apply(ThemeMode theme, string accentColor)
    {
        var changed = Theme != theme || AccentColor != accentColor;
        Theme = theme;
        AccentColor = accentColor;
        if (changed) OnChanged?.Invoke();
    }
}

const STORAGE_KEY = "app_theme";

export function load() {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return null;
    try { return JSON.parse(raw); }
    catch { return null; }
}

export function save(theme, accentColor) {
    localStorage.setItem(STORAGE_KEY, JSON.stringify({ theme, accentColor }));
    applyToDom(theme, accentColor);
}

export function applyToDom(theme, accentColor) {
    document.documentElement.setAttribute("data-theme", theme.toLowerCase());
    document.documentElement.style.setProperty("--accent-color", accentColor);
}

@*
    Interactive island placed in the static layout.
    It shares the circuit (and scoped ThemeService) with every other
    @rendermode InteractiveServer component on the current page.
    On init it hydrates ThemeService from localStorage; on changes it
    persists back and updates the DOM via JS interop.
*@
@rendermode InteractiveServer
@implements IAsyncDisposable
@inject ThemeService ThemeService
@inject IJSRuntime JS

@code {
    private IJSObjectReference? _module;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (!firstRender) return;

        _module = await JS.InvokeAsync<IJSObjectReference>(
            "import", "./js/theme.js");

        // Hydrate from localStorage
        var saved = await _module.InvokeAsync<ThemeStorageDto?>("load");
        if (saved is not null
            && Enum.TryParse<ThemeMode>(saved.Theme, true, out var mode))
        {
            ThemeService.Apply(mode, saved.AccentColor ?? ThemeService.AccentColor);
        }

        // Apply current values to DOM
        await ApplyAsync();

        ThemeService.OnChanged += HandleChanged;
    }

    private async void HandleChanged()
    {
        await InvokeAsync(async () =>
        {
            await ApplyAsync();
            StateHasChanged();
        });
    }

    private async Task ApplyAsync()
    {
        if (_module is null) return;
        await _module.InvokeVoidAsync("save",
            ThemeService.Theme.ToString(), ThemeService.AccentColor);
    }

    public async ValueTask DisposeAsync()
    {
        ThemeService.OnChanged -= HandleChanged;
        if (_module is not null)
            await _module.DisposeAsync();
    }

    private sealed class ThemeStorageDto
    {
        public string? Theme { get; set; }
        public string? AccentColor { get; set; }
    }
}

